'use client';

import React, { useState } from 'react';
import { ServerEvent } from '../lib/types';

interface EventLogDrawerProps {
  isOpen: boolean;
  onClose: () => void;
  logs: ServerEvent[];
  onClear: () => void;
}

export const EventLogDrawer: React.FC<EventLogDrawerProps> = ({
  isOpen,
  onClose,
  logs,
  onClear,
}) => {
  const [copied, setCopied] = useState(false);

  if (!isOpen) return null;

  const copyAll = () => {
    navigator.clipboard.writeText(JSON.stringify(logs, null, 2));
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div
      style={{
        position: 'fixed',
        bottom: 0,
        right: 0,
        width: '450px',
        maxHeight: '500px',
        backgroundColor: '#0E1A2B',
        color: '#F1F4F9',
        borderTopLeftRadius: '10px',
        boxShadow: '-4px -4px 20px rgba(0,0,0,0.3)',
        zIndex: 1000,
        display: 'flex',
        flexDirection: 'column',
        fontFamily: 'monospace',
      }}
      role="region"
      aria-label="Registro de eventos en tiempo real"
    >
      <div
        style={{
          padding: '0.75rem 1rem',
          borderBottom: '1px solid #23344E',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
        }}
      >
        <span style={{ fontWeight: 'bold', fontSize: '0.9rem' }}>
          📡 Registro de Eventos ({logs.length})
        </span>
        <div style={{ display: 'flex', gap: '0.5rem' }}>
          <button
            onClick={copyAll}
            style={{
              backgroundColor: '#1E2D42',
              color: '#FFF',
              border: '1px solid #3A4B63',
              borderRadius: '4px',
              padding: '0.2rem 0.5rem',
              fontSize: '0.75rem',
              cursor: 'pointer',
            }}
          >
            {copied ? '¡Copiado!' : 'Copiar todo (JSON)'}
          </button>
          <button
            onClick={onClear}
            style={{
              backgroundColor: '#1E2D42',
              color: '#FFF',
              border: '1px solid #3A4B63',
              borderRadius: '4px',
              padding: '0.2rem 0.5rem',
              fontSize: '0.75rem',
              cursor: 'pointer',
            }}
          >
            Limpiar
          </button>
          <button
            onClick={onClose}
            style={{
              backgroundColor: 'transparent',
              color: '#FFF',
              border: 'none',
              fontSize: '1rem',
              cursor: 'pointer',
            }}
          >
            ✕
          </button>
        </div>
      </div>

      <div
        style={{
          padding: '0.8rem',
          overflowY: 'auto',
          flex: 1,
          display: 'flex',
          flexDirection: 'column',
          gap: '0.75rem',
          fontSize: '0.78rem',
        }}
      >
        {logs.length === 0 ? (
          <div style={{ color: '#647286', textAlign: 'center', padding: '1rem' }}>
            No hay eventos registrados aún.
          </div>
        ) : (
          logs.map((log, index) => (
            <div
              key={index}
              style={{
                backgroundColor: log.isWarning ? '#3D1518' : '#17253B',
                border: log.isWarning ? '1px solid #D42F3C' : '1px solid #23344E',
                borderRadius: '6px',
                padding: '0.6rem',
              }}
            >
              <div
                style={{
                  display: 'flex',
                  justifyContent: 'space-between',
                  marginBottom: '0.3rem',
                  color: log.isWarning ? '#FCE7E9' : '#8CA3CB',
                  fontWeight: 'bold',
                }}
              >
                <span>
                  {log.isWarning && '⚠️ '}
                  {log.type}
                </span>
                <span style={{ fontSize: '0.7rem', color: '#647286' }}>{log.timestamp}</span>
              </div>
              <pre
                style={{
                  margin: 0,
                  whiteSpace: 'pre-wrap',
                  wordBreak: 'break-all',
                  color: '#D6DDE8',
                }}
              >
                {JSON.stringify(log.payload, null, 2)}
              </pre>
            </div>
          ))
        )}
      </div>
    </div>
  );
};
